import{_ as e,o as t,c as r,ag as o}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"外观与背景","description":"","frontmatter":{},"headers":[],"relativePath":"guide/appearance.md","filePath":"guide/appearance.md","lastUpdated":null}'),n={name:"guide/appearance.md"};function i(l,a,d,p,h,s){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="外观与背景" tabindex="-1">外观与背景 <a class="header-anchor" href="#外观与背景" aria-label="Permalink to &quot;外观与背景&quot;">​</a></h1><h2 id="主题设置" tabindex="-1">主题设置 <a class="header-anchor" href="#主题设置" aria-label="Permalink to &quot;主题设置&quot;">​</a></h2><p>首页调色盘按钮打开主题设置。设置按外观与颜色、概览与字段、布局与网络、地区与资产、扩展服务分类。</p><p>外观偏好先保存在当前浏览器。管理员可以点击“保存为站点默认”，让新访客使用相同的默认配置。</p><h2 id="卡片透明度" tabindex="-1">卡片透明度 <a class="header-anchor" href="#卡片透明度" aria-label="Permalink to &quot;卡片透明度&quot;">​</a></h2><p>进入 <strong>外观与颜色 → 卡片透明度</strong>。数值越大，玻璃卡片越透明；滑块只改变底色，文字和图表不会一起变淡。支持实时预览和一键恢复默认。</p><h2 id="布局预设" tabindex="-1">布局预设 <a class="header-anchor" href="#布局预设" aria-label="Permalink to &quot;布局预设&quot;">​</a></h2><p>日常展示使用节点卡片，紧凑巡检使用表格。桌面和手机可分别选择布局。首次配置向导可以重新打开，应用前可查看配置摘要；取消不会改动站点配置。</p><h2 id="图片与视频" tabindex="-1">图片与视频 <a class="header-anchor" href="#图片与视频" aria-label="Permalink to &quot;图片与视频&quot;">​</a></h2><p>背景设置支持图片和视频直链、本机偏好，以及配套服务提供的文件上传和服务器下载。直接下载需要公开的媒体地址；网页分享页、需要登录的链接或内网地址不能作为媒体直链。</p><p>播放列表可选择顺序、随机或保持当前媒体。视频可按完整时长播放，也可按固定时间切换。使用“站点背景”可撤销浏览器中的个人覆盖。</p><h2 id="语言与时区" tabindex="-1">语言与时区 <a class="header-anchor" href="#语言与时区" aria-label="Permalink to &quot;语言与时区&quot;">​</a></h2><p>主题支持简体中文、繁體中文、English、日本語和 한국어。首页时间卡可打开世界时钟并切换时区；节点名称和第三方日志会保持原文。</p>',13)])])}const _=e(n,[["render",i]]);export{u as __pageData,_ as default};
